def get_smallest_divisible_number_brute_force(max_factor):
    """
    Get the smallest divisible number by all [1..max_factor] numbers by brute force.
    """
    number_i = max_factor
    while True:
        divisible = True
        for factor_i in range(1, max_factor+1):
            if number_i % factor_i > 0:
                divisible = False
                break
        if divisible:
            return number_i
        number_i += 1

